<div class="page-title">Review Exceptions</div><p class="page-subtitle">Skip scheduled reviews for Day Off, PTO, holidays, personal issues, or any other no-trading period.</p>
<div class="card"><h2>Add exception</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="grid"><p><label>Period</label><select name="period_type"><option value="day">Day</option><option value="week">Week</option><option value="month">Month</option><option value="year">Year</option></select></p><p><label>Start date</label><input type="date" name="start_date" required></p><p><label>End date</label><input type="date" name="end_date" required></p><p><label>Reason</label><input name="reason" placeholder="Day Off / PTO / Personal issue"></p></div><div class="actions"><button>Skip Reviews</button></div></form></div>
<div class="card"><h2>Scheduled exceptions</h2><?php if(!$exceptions):?><p class="muted">No exceptions configured.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Period</th><th>Period start</th><th>Reason</th><th>Created</th></tr></thead><tbody><?php foreach($exceptions as $x):?><tr><td><?=e(ucfirst($x['period_type']))?></td><td><?=e($x['period_start'])?></td><td><?=e($x['reason'])?></td><td><?=e($x['created_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
